import{_ as t,o as e,c as s,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"管理与监控","description":"监控的目标是在用户发现故障之前发现故障。会敲 rabbitmqctl 不等于会运维，真正的能力是看到指标就能判断「这是正常波动还是出问题了」。这一章讲怎么搭起这套判断力，而不是堆命令。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/08-operations/chapter-01-management.md","filePath":"rabbitmq/08-operations/chapter-01-management.md"}'),n={name:"rabbitmq/08-operations/chapter-01-management.md"};function r(l,a,d,p,h,c){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="管理与监控" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/08-operations/chapter-01-management.md">管理与监控 <a class="header-anchor" href="#管理与监控" aria-label="Permalink to &quot;管理与监控&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><p data-src-line="3" data-src-file="rabbitmq/08-operations/chapter-01-management.md">监控的目标是在用户发现故障之前发现故障。会敲 <code>rabbitmqctl</code> 不等于会运维，真正的能力是看到指标就能判断「这是正常波动还是出问题了」。这一章讲怎么搭起这套判断力，而不是堆命令。</p></blockquote><h2 id="_1-三个必盯指标" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/08-operations/chapter-01-management.md">1. 三个必盯指标 <a class="header-anchor" href="#_1-三个必盯指标" aria-label="Permalink to &quot;1. 三个必盯指标&quot;">​</a></h2><p data-src-line="7" data-src-file="rabbitmq/08-operations/chapter-01-management.md">内存、磁盘和队列堆积是 RabbitMQ 监控里需要优先盯的三类指标。盯住它们，比盯一屏花花绿绿的仪表盘有用得多。</p><p data-src-line="9" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><strong>内存水位</strong>。<code>vm_memory_high_watermark</code> 设置内存告警的触发阈值，超过后节点触发内存告警并阻塞发布消息的连接。默认 0.6（相对值，即检测到可用内存的 60%）。告警阈值不能照抄一个数，要看这个值相对水位的余量。内存使用持续逼近水位，可能来自队列堆积，也可能是连接、通道、队列进程或运行时内存增长，要用 <code>rabbitmq-diagnostics memory_breakdown</code> 定位具体来源，而不是直接归因于消费不过来。</p><p data-src-line="11" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><strong>磁盘水位</strong>。<code>disk_free_limit</code> 默认 50MB，这是给开发环境的，生产必须调大。磁盘告警的意义在于提前量，从「低于阈值」到「磁盘写满」之间要留出足够时间让运维介入。剩余空间告警线要按磁盘消耗速率留足处置时间，而不是剩 100MB 才报警；磁盘消耗不只来自新消息，还有持久化写入、消息分页和其他进程的占用。</p><p data-src-line="13" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><strong>队列堆积</strong>。<code>messages_ready</code> 持续上涨是堆积，但「多少算多」没有绝对标准。一条消费速率 1 万 msg/s 的队列积 10000 条只是约 1 秒的工作量，一条 1 msg/s 的队列积 10000 条相当于近 3 小时的工作量。这个估算以消费速率稳定为前提，不能直接用来判断消费者停了多久。阈值必须跟着队列的吞吐走，写死一个 10000 对所有队列一刀切，要么天天误报，要么真出事了不响。</p><h2 id="_2-指标怎么拿" tabindex="-1" data-src-line="15" data-src-file="rabbitmq/08-operations/chapter-01-management.md">2. 指标怎么拿 <a class="header-anchor" href="#_2-指标怎么拿" aria-label="Permalink to &quot;2. 指标怎么拿&quot;">​</a></h2><p data-src-line="17" data-src-file="rabbitmq/08-operations/chapter-01-management.md">两个入口，分工不同。</p><p data-src-line="19" data-src-file="rabbitmq/08-operations/chapter-01-management.md">Management UI（15672 端口）适合人肉排查，看单个队列、单个连接的实时状态。Prometheus 适合长期监控和告警，<code>rabbitmq_prometheus</code> 插件默认在 15692 端口暴露 <code>/metrics</code> 端点，接进 Grafana 或告警系统后可以基于历史基线判断趋势。默认 <code>/metrics</code> 只返回节点级聚合指标，队列级指标（如单个队列的消息数、消费者数）要通过 <code>/metrics/per-object</code> 采集，逐对象采集在队列数量大时开销明显。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmq-plugins</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmq_management</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbitmq_prometheus</span></span></code></pre></div><p data-src-line="25" data-src-file="rabbitmq/08-operations/chapter-01-management.md">单点排查看 Management UI，趋势和告警看 Prometheus。别用 Management UI 当告警源，它只保留近期指标，不适合长期监控存储。</p><h2 id="_3-关键指标" tabindex="-1" data-src-line="27" data-src-file="rabbitmq/08-operations/chapter-01-management.md">3. 关键指标 <a class="header-anchor" href="#_3-关键指标" aria-label="Permalink to &quot;3. 关键指标&quot;">​</a></h2><table tabindex="0"><thead data-src-line="29" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><tr data-src-line="29" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><th style="text-align:left;">指标</th><th style="text-align:left;">含义</th><th style="text-align:left;">告警思路</th></tr></thead><tbody data-src-line="31" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><tr data-src-line="31" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><td style="text-align:left;"><code>rabbitmq_queue_messages_ready</code></td><td style="text-align:left;">待消费消息数</td><td style="text-align:left;">相对队列吞吐定阈值，持续增长或积压超过业务可接受范围时告警</td></tr><tr data-src-line="32" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><td style="text-align:left;"><code>rabbitmq_queue_messages_unacked</code></td><td style="text-align:left;">已投递未确认</td><td style="text-align:left;">持续上涨时检查消费者处理耗时、预取配置与确认行为</td></tr><tr data-src-line="33" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><td style="text-align:left;"><code>rabbitmq_queue_consumers</code></td><td style="text-align:left;">队列消费者数</td><td style="text-align:left;">预期应有消费者的队列，消费者数为 0 时告警</td></tr><tr data-src-line="34" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><td style="text-align:left;"><code>rabbitmq_connections</code></td><td style="text-align:left;">连接数</td><td style="text-align:left;">结合增长速率、业务基线与文件描述符限制排查异常增长</td></tr><tr data-src-line="35" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><td style="text-align:left;"><code>rabbitmq_process_resident_memory_bytes</code></td><td style="text-align:left;">节点内存占用</td><td style="text-align:left;">逼近内存水位线 <code>rabbitmq_resident_memory_limit_bytes</code> 时告警</td></tr><tr data-src-line="36" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><td style="text-align:left;"><code>rabbitmq_disk_space_available_bytes</code></td><td style="text-align:left;">磁盘剩余</td><td style="text-align:left;">逼近磁盘水位线 <code>rabbitmq_disk_space_available_limit_bytes</code> 时告警</td></tr></tbody></table><p data-src-line="38" data-src-file="rabbitmq/08-operations/chapter-01-management.md">这张表里的「告警思路」才是重点。指标名记不住可以查，但每个指标对应什么故障形态要清楚。</p><h2 id="_4-命令按用途分组" tabindex="-1" data-src-line="40" data-src-file="rabbitmq/08-operations/chapter-01-management.md">4. 命令按用途分组 <a class="header-anchor" href="#_4-命令按用途分组" aria-label="Permalink to &quot;4. 命令按用途分组&quot;">​</a></h2><p data-src-line="42" data-src-file="rabbitmq/08-operations/chapter-01-management.md">命令不是拿来背的，是按「此刻要回答什么问题」来查的。</p><p data-src-line="44" data-src-file="rabbitmq/08-operations/chapter-01-management.md">看集群是否健康：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster_status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p data-src-line="51" data-src-file="rabbitmq/08-operations/chapter-01-management.md">看队列状态，判断堆积和消费者：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list_queues</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> messages_ready</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> messages_unacknowledged</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consumers</span></span></code></pre></div><p data-src-line="57" data-src-file="rabbitmq/08-operations/chapter-01-management.md">看连接和通道，排查连接泄漏：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list_connections</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> peer_host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list_channels</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connection_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> consumer_count</span></span></code></pre></div><p data-src-line="64" data-src-file="rabbitmq/08-operations/chapter-01-management.md">每一条命令都在回答一个具体问题。不知道自己要问什么，敲再多命令也看不出结论。</p><h2 id="_5-日志" tabindex="-1" data-src-line="66" data-src-file="rabbitmq/08-operations/chapter-01-management.md">5. 日志 <a class="header-anchor" href="#_5-日志" aria-label="Permalink to &quot;5. 日志&quot;">​</a></h2><p data-src-line="68" data-src-file="rabbitmq/08-operations/chapter-01-management.md">日志位置取决于安装方式。Linux 系统包安装通常在 <code>/var/log/rabbitmq/</code> 下，命名带节点名；容器部署可能输出到标准输出，也可以通过配置修改位置。排查前可用 <code>rabbitmq-diagnostics -q log_location</code> 确认当前节点的日志位置。默认 info 级别够用，排查时才临时调到 debug，查完调回原级别，长期 debug 会淹没真正有用的信息。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_log_level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 排查完恢复原级别，如下例恢复为 info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set_log_level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span></code></pre></div><p data-src-line="76" data-src-file="rabbitmq/08-operations/chapter-01-management.md">日志最有价值的场景是节点启动失败和集群分裂，这两类问题的根因在日志里通常有明确线索。</p><h2 id="_6-常用运维操作" tabindex="-1" data-src-line="78" data-src-file="rabbitmq/08-operations/chapter-01-management.md">6. 常用运维操作 <a class="header-anchor" href="#_6-常用运维操作" aria-label="Permalink to &quot;6. 常用运维操作&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop_app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 停止 RabbitMQ 应用，Erlang 节点仍在运行</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 重置节点为初始状态，删除持久化消息与管理数据，执行前需停止应用</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forget_cluster_node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rabbit@failed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 从当前节点移除已离线的节点，先确认其已永久下线</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purge_queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue_name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 清空指定队列消息，执行前确认业务允许丢弃</span></span></code></pre></div><p data-src-line="87" data-src-file="rabbitmq/08-operations/chapter-01-management.md"><code>reset</code> 会把节点重置为初始状态，删除持久化消息与管理数据，执行前必须停止应用并确认该节点数据可以丢弃；重新加入集群不是执行它的充分条件。这几条命令用途和风险各不相同，不是一套可依次执行的通用恢复流程，执行前先确认故障类型与影响范围。这些操作对应的故障排查路径见<a href="./chapter-03-troubleshooting.html">常见问题排查</a>。</p>`,31)])])}const b=t(n,[["render",r]]);export{m as __pageData,b as default};
